package com.example.agroconnect.controller;
import com.example.agroconnect.model.Farmer; import com.example.agroconnect.repository.FarmerRepository; import jakarta.servlet.http.HttpSession; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/eligibility") @CrossOrigin(origins="http://localhost:5173",allowCredentials="true") public class EligibilityController {
 private final FarmerRepository farmers; public EligibilityController(FarmerRepository f){farmers=f;} public record EligibilityRequest(double monthlyIncome,double monthlyExpenses,double existingMonthlyDebt,double requestedAmount){}
 @PostMapping("/farmer/{farmerId}") public ResponseEntity<?> check(@PathVariable Long farmerId,@RequestBody EligibilityRequest r,HttpSession session){Farmer f=farmers.findById(farmerId).orElse(null);if(f==null)return ResponseEntity.notFound().build();Object uid=session.getAttribute("userId");if(uid==null)return ResponseEntity.status(401).body("Please login first");if(!"ADMIN".equals(session.getAttribute("role"))&&(f.getUser()==null||!f.getUser().getId().toString().equals(uid.toString())))return ResponseEntity.status(403).body("Not allowed");if(r.monthlyIncome()<0||r.monthlyExpenses()<0||r.existingMonthlyDebt()<0||r.requestedAmount()<=0)return ResponseEntity.badRequest().body("Financial values must be non-negative and requestedAmount must be positive");double net=r.monthlyIncome()-r.monthlyExpenses()-r.existingMonthlyDebt();double payment=Math.max(0,net*0.30),max=payment*36;boolean ok=net>0&&r.requestedAmount()<=max;List<String> reasons=new ArrayList<>();if(net<=0)reasons.add("Income does not exceed expenses and existing debt");if(r.requestedAmount()>max)reasons.add("Requested amount is above this tool's estimated affordability range");if(reasons.isEmpty())reasons.add("Entered figures pass this basic affordability estimate");Map<String,Object> out=new LinkedHashMap<>();out.put("farmerId",farmerId);out.put("monthlyNetAfterExpensesAndDebt",Math.round(net*100.0)/100.0);out.put("suggestedMaximumMonthlyPayment",Math.round(payment*100.0)/100.0);out.put("estimatedAffordableAmount",Math.round(max*100.0)/100.0);out.put("requestedAmount",r.requestedAmount());out.put("preliminaryEstimate",ok?"WITHIN_ESTIMATE":"OUTSIDE_ESTIMATE");out.put("reasons",reasons);out.put("disclaimer","Educational estimate only; not a bank decision, credit assessment, or loan approval. Real lender criteria and interest rates may differ.");return ResponseEntity.ok(out);}
 @GetMapping("/documents-checklist") public Map<String,Object> checklist(){return Map.of("items",List.of("Identity proof (as requested by lender)","Address proof","Land ownership/lease records if applicable","Bank account details/passbook","Crop and cultivation details","Income/expense details","Lender-specific application form"),"note","Requirements vary by lender, scheme, state and applicant. Verify with the official lender.");}
}
